from src.rag.retriever import RAGRetriever
from src.rag.prompt import build_safety_prompt

def test_rag_pipeline_real():
    """
    Test the complete RAG retrieval and prompt generation
    using real Ollama embeddings and PostgreSQL.
    """

    # Simulate a visual description generated by the vision model.
    visual_description = (
        "A person appears to be lying on the ground "
        "on an icy outdoor surface."
    )

    # Create the real RAG retriever.
    retriever = RAGRetriever()

    # Generate a real embedding and retrieve guideline chunks
    # from the PostgreSQL vector database.
    chunks = retriever.retrieve(
        visual_description,
        top_k=3,
    )

    # Ensure that the database returned relevant guideline chunks.
    assert len(chunks) > 0

    # Build the prompt using the actual retrieved chunks.
    prompt = build_safety_prompt(
        visual_description,
        chunks,
    )

    # Print the prompt for manual inspection.
    print("\n" + "=" * 60)
    print(prompt)
    print("=" * 60)

    # Verify that the prompt contains the incident description.
    assert visual_description in prompt

    # Verify that the retrieved guideline content is included.
    for chunk in chunks:
        assert chunk.content in prompt
        assert chunk.document_name in prompt
        assert chunk.section in prompt
